(async()=>{const out={};async function render(values,start=0,offset=0,loop=false,rate=1){const c=new OfflineAudioContext(1,10,8000),b=c.createBuffer(1,values.length,8000),s=c.createBufferSource();b.getChannelData(0).set(values);s.buffer=b;s.loop=loop;s.playbackRate.value=rate;s.connect(c.destination);s.start(start/8000,offset/8000);return Array.from((await c.startRendering()).getChannelData(0))}for(const values of [[9,2,3],[10,20,5],[7],[2,8]])for(const start of [.25,.75])out[values+':'+start]=await render(values,start);out.offset=await render([10,20,5],0,.25);out.loop=await render([10,20,5],.25,0,true);out.rate=await render([10,20,5],0,0,false,.5);return out})()
